// Uploads the built artifact to the release bucket.
const fs = require("fs");
const https = require("https");

const BUCKET = process.env.RELEASE_BUCKET || "release-bucket";
const REGION = process.env.RELEASE_BUCKET_REGION || "us-east-1";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function hmac(key, data) {
  return require("crypto").createHmac("sha256", key).update(data).digest();
}

function sha256hex(data) {
  return require("crypto").createHash("sha256").update(data).digest("hex");
}

function awsV4Sign(method, host, path, body) {
  const now = new Date();
  const amzDate = now.toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
  const dateStamp = amzDate.slice(0, 8);
  const payloadHash = sha256hex(body);

  const headers = {
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
  };
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalHeaders =
    Object.keys(headers)
      .sort()
      .map((h) => `${h}:${headers[h]}\n`)
      .join("");
  const canonicalRequest = [
    method,
    path,
    "",
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");

  const credentialScope = `${dateStamp}/${REGION}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    credentialScope,
    sha256hex(canonicalRequest),
  ].join("\n");

  const kDate = hmac("AWS4" + process.env.AWS_SECRET_ACCESS_KEY, dateStamp);
  const kRegion = hmac(kDate, REGION);
  const kService = hmac(kRegion, "s3");
  const kSigning = hmac(kService, "aws4_request");
  const signature = require("crypto")
    .createHmac("sha256", kSigning)
    .update(stringToSign)
    .digest("hex");

  headers["authorization"] =
    `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/${credentialScope}, ` +
    `SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return headers;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  // PUT body to bucket BUCKET under object name
  if (process.env.OFFLINE) {
    console.log(`uploaded ${name} (${body.length} bytes) [offline]`);
    return;
  }
  const host = `${BUCKET}.s3.${REGION}.amazonaws.com`;
  const path = `/${name}`;
  const headers = awsV4Sign("PUT", host, path, body);

  const req = https.request(
    { host, path, method: "PUT", headers },
    (res) => {
      res.resume();
      res.on("end", () => {
        if (res.statusCode === 200) {
          console.log(`uploaded ${name} (${body.length} bytes)`);
        } else {
          console.error(`upload failed: HTTP ${res.statusCode}`);
          process.exit(1);
        }
      });
    }
  );
  req.on("error", (err) => {
    console.error(`upload failed: ${err.message}`);
    process.exit(1);
  });
  req.write(body);
  req.end();
}

main();

